  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Cycle Time$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description, version)
    VALUES (NULL, $q$Injection Molding - Cycle Time$q$, 'process', 'single', false, true, true, $q$Injection cycle time = (Injection + Cooling + Plasticizing beyond cooling + Ejection) x Cycle Time Adjustment Factor (formula registry F-08 v2, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula); it runs from the end of filling to ejection, so holding pressure is inside it and is not added again. Injection = shot melt volume / (the press injection rate x injectionRateMultiplier) x the injectionTimeAdjustmentFactors for cavities and gates (F-05 v2, VALIDATED). Plasticizing = the shot's GPPS-equivalent mass / (the press plasticizing rate x plasticizingRateMultiplier), the press's own rate or else plasticizingRateByClampForce at its clamp force (F-20, ASSUMED); the screw recovers while the part cools, so only the part longer than cooling adds to the cycle. Ejection = mold open and close (the press Euromap 6 dry cycle, F-07) + the ejector stroke out and back: numEjectorCycles x 2 x ejectorDistanceFactor x the part height, at ejectorPercentMaxMachineVelocity of the platen speed, the speed being 2 x dryCycleStrokeFactor x the opening stroke / the dry cycle (F-21, ASSUMED: the reference states these variables, not the formula). Not modelled, because the reference has no formula or the part no input: robotic part handling (partHandlingTimes; the reference default ejection is gravity), material handling, slides and lifters. Rounded as the engine does: cooling to 0.1 s, the times and the total to 0.01 s.$q$, 2)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Injection cycle time = (Injection + Cooling + Plasticizing beyond cooling + Ejection) x Cycle Time Adjustment Factor (formula registry F-08 v2, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula); it runs from the end of filling to ejection, so holding pressure is inside it and is not added again. Injection = shot melt volume / (the press injection rate x injectionRateMultiplier) x the injectionTimeAdjustmentFactors for cavities and gates (F-05 v2, VALIDATED). Plasticizing = the shot's GPPS-equivalent mass / (the press plasticizing rate x plasticizingRateMultiplier), the press's own rate or else plasticizingRateByClampForce at its clamp force (F-20, ASSUMED); the screw recovers while the part cools, so only the part longer than cooling adds to the cycle. Ejection = mold open and close (the press Euromap 6 dry cycle, F-07) + the ejector stroke out and back: numEjectorCycles x 2 x ejectorDistanceFactor x the part height, at ejectorPercentMaxMachineVelocity of the platen speed, the speed being 2 x dryCycleStrokeFactor x the opening stroke / the dry cycle (F-21, ASSUMED: the reference states these variables, not the formula). Not modelled, because the reference has no formula or the part no input: robotic part handling (partHandlingTimes; the reference default ejection is gravity), material handling, slides and lifters. Rounded as the engine does: cooling to 0.1 s, the times and the total to 0.01 s.$q$, version = 2, updated_at = now() WHERE id = v_id;
  END IF;

